args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?birthDate ?label WHERE {
  VALUES ?person { dbr:Denise_Kandel dbr:Bruce_Robinson }
  OPTIONAL { ?person dbo:birthDate ?birthDate }
  OPTIONAL { ?person rdfs:label ?label FILTER (lang(?label) = "en") }
} ORDER BY ?person

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?younger ?youngerLabel ?birthDate WHERE {
  VALUES ?person { dbr:Denise_Kandel dbr:Bruce_Robinson }
  ?person dbo:birthDate ?birthDate .
  BIND(?person AS ?younger)
  OPTIONAL { ?person rdfs:label ?youngerLabel FILTER(lang(?youngerLabel) = "en") }
} ORDER BY DESC(?birthDate) LIMIT 1

